<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Takvim senkronizasyonu</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:32px auto;padding:0 16px}.panel{background:#fff;padding:22px;border-radius:14px;margin:14px 0}.muted{color:#68756c}.url{padding:12px;background:#f1f6f2;border:1px solid #dbe8dd;border-radius:8px;overflow-wrap:anywhere}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}button,.btn{display:inline-block;background:#176b50;color:#fff;padding:10px 14px;border:0;border-radius:8px;text-decoration:none;font-weight:700;cursor:pointer}.danger{background:#a43}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #edf0ed;font-size:13px}.table-wrap{overflow-x:auto}</style><?php require APP_ROOT . '/views/site/partials/admin-theme.php'; ?></head><body><main class="wrap"><h1>Takvim senkronizasyonu</h1><p class="muted">Harici iCal takvimlerinin otomatik eşitlenmesi ve sistemdeki müsaitlik bloklarının dışa aktarılması.</p>
<?php if(!empty($calendarMessage)): ?><div class="url"><?= e($calendarMessage) ?></div><?php endif; ?>
<section class="panel"><h2>cPanel Cron Jobs bağlantısı</h2><p class="muted">Bu gizli URL'yi 30 dakikada bir çağıracak bir Cron Job oluşturun. URL'yi herkese açık paylaşmayın.</p><div class="url" id="calendar-cron-url"><?= e($cronUrl) ?></div><div class="actions"><button type="button" onclick="navigator.clipboard&&navigator.clipboard.writeText(document.getElementById('calendar-cron-url').textContent)">URL'yi kopyala</button><form method="post" action="/admin/calendar-sync/rotate-token"><?= csrf_field() ?><button class="danger" type="submit" onclick="return confirm('Mevcut Cron URL'si geçersiz kılınacak. Devam edilsin mi?')">Cron tokenini yenile</button></form><form method="post" action="/admin/calendar-sync/run-now"><?= csrf_field() ?><button type="submit">Şimdi tüm takvimleri eşitle</button></form></div><p class="muted">cPanel → Cron Jobs → Common Settings: Every 30 Minutes. Komut alanına şu URL'yi curl ile çağıran komutu girin: <code>curl -fsS "<?= e($cronUrl) ?>"</code></p></section>
<section class="panel"><h2>Takvim kaynakları</h2><?php if(!$feeds): ?><p class="muted">Henüz takvim kaynağı eklenmedi.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>İlan</th><th>Takvim</th><th>Yön</th><th>Durum</th><th>Son eşitleme</th></tr></thead><tbody><?php foreach($feeds as $feed): ?><tr><td><?= e($feed['property_title']) ?><small style="display:block"><?= e($feed['city']??'') ?></small></td><td><?= e($feed['label']) ?></td><td><?= $feed['direction']==='import'?'İçe aktar':'Dışa aktar' ?></td><td><?= e($feed['last_sync_status']??'Hazır') ?><small style="display:block"><?= e($feed['last_sync_message']??'') ?></small></td><td><?= !empty($feed['last_synced_at'])?e(date('d.m.Y H:i',strtotime($feed['last_synced_at']))):'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
